insert into services (id, name, icon, price, unit, text, visible, sort) values ('tattoo', 'Тату', 'dagger', 1500, '', 'Від мініатюри до рукава. Ескіз погоджуємо до сеансу, а не під машинкою.', true, 1) on conflict (id) do nothing;
insert into services (id, name, icon, price, unit, text, visible, sort) values ('piercing', 'Пірсинг', 'star', 600, '', 'Вуха, ніс, брова, губа. Титанові прикраси імплант-класу вже в ціні.', true, 2) on conflict (id) do nothing;
insert into services (id, name, icon, price, unit, text, visible, sort) values ('coverup', 'Перекриття', 'flame', 3000, '', 'Ховаємо старе або невдале тату під нову роботу, якої не соромно.', true, 3) on conflict (id) do nothing;
insert into services (id, name, icon, price, unit, text, visible, sort) values ('sketch', 'Ескіз на замовлення', 'bolt', 800, '', 'Унікальний малюнок тільки під вас. Два раунди правок без доплат.', true, 4) on conflict (id) do nothing;
insert into services (id, name, icon, price, unit, text, visible, sort) values ('correction', 'Корекція', 'horns', 1200, '', 'Оновлюємо вицвілі контури та колір, виправляємо чужі помилки.', true, 5) on conflict (id) do nothing;
insert into services (id, name, icon, price, unit, text, visible, sort) values ('removal', 'Лазерне видалення', 'skull', 900, '/сеанс', 'Видалення або висвітлення старого тату під перекриття. Ціна за сеанс.', true, 6) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('ostap', 'Остап Коваль', 'Шрам', 'Реалізм ч/б', array['Реалізм', 'Портрети', 'Чорно-сіре']::text[], 12, '1 200 ₴/год', 'Портрети, тварини, кінематографічні сюжети. Працює з тінню так, що тату виглядає як фото на шкірі.', 'assets/masters/master-1.jpg', 'top', true, 1) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('solomiia', 'Соломія Гнатюк', 'Ніч', 'Графіка / дотворк', array['Графіка', 'Дотворк', 'Орнамент']::text[], 8, '1 000 ₴/год', 'Орнаменти, ботаніка, сакральна геометрія. Чисті лінії та крапкова тінь, що гарно старіє разом з вами.', 'assets/masters/master-2.jpg', 'top', true, 2) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('taras', 'Тарас Мельник', 'Борода', 'Олдскул / неотрад', array['Олдскул', 'Неотрад', 'Колір']::text[], 10, '1 500–6 000 ₴', 'Ластівки, кинджали, троянди, пантери. Жирний контур і насичений колір: класика, яка не виходить з моди.', 'assets/masters/master-3.jpg', 'top', true, 3) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('alex', 'Алекс Мороз', 'Вайпер', 'Пірсинг / мініатюри', array['Пірсинг', 'Мініатюри', 'Fine line']::text[], 6, 'від 600 ₴', 'Проколи будь-якої складності та тонкі мініатюри. Стерильність, яку можна перевірити: усе відкривається при вас.', 'assets/masters/master-4.jpg', 'wide', true, 4) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('iryna', 'Ірина Савчук', 'Лисиця', 'Акварель / колір', array['Акварель', 'Колір', 'Ботаніка']::text[], 7, '1 100 ₴/год', 'Розмиті кольорові плями, квіти, тварини в акварельній техніці. Контур підбирає так, щоб колір не поплив з роками.', 'assets/masters/master-5.jpg', 'wide', true, 5) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('dana', 'Дана Остапчук', 'Кобра', 'Леттеринг / каліграфія', array['Леттеринг', 'Каліграфія', 'Шрифти']::text[], 9, '900–4 000 ₴', 'Написи будь-якою мовою, власні шрифти, готичний і чикано-леттеринг. Перевіряє кожну літеру перед сеансом.', 'assets/masters/master-6.jpg', 'wide', true, 6) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('bohdan', 'Богдан Яремчук', 'Тінь', 'Перекриття / корекція', array['Перекриття', 'Корекція', 'Блекворк']::text[], 14, '1 300 ₴/год', 'Рятує те, що здавалося безнадійним: старі наколки, розпливлі контури, невдалі написи. Перекриває так, що старого не видно.', '', 'top', true, 7) on conflict (id) do nothing;
insert into masters (id, name, nick, style, tags, exp, price, about, photo, photo_pos, visible, sort) values ('vlad', 'Влад Данилюк', 'Голка', 'Японський стиль', array['Ірезумі', 'Великі проєкти', 'Рукави']::text[], 11, 'від 2 500 ₴/сеанс', 'Дракони, коі, хвилі та маски ханья. Веде великі проєкти на спину чи рукав від ескізу до останнього сеансу.', '', 'top', true, 8) on conflict (id) do nothing;
