insert into reviews (id, text, author, caption, visible, sort) values ('r-1', 'Робила перше тату в Соломії. Боялася до тремтіння, а вийшла з посмішкою. Пів року минуло, лінії як у перший день.', 'Олена, 24', 'графіка на передпліччі', true, 1) on conflict (id) do nothing;
insert into reviews (id, text, author, caption, visible, sort) values ('r-2', 'Перекрили армійську наколку, яку я ховав п’ятнадцять років. Тепер на плечі ворон, і я знову ходжу у футболках.', 'Андрій, 38', 'перекриття у Богдана', true, 2) on conflict (id) do nothing;
insert into reviews (id, text, author, caption, visible, sort) values ('r-3', 'Проколов хрящ у Алекса. Все стерильно, швидко, детально пояснили догляд. Загоїлось без жодних проблем.', 'Максим, 19', 'пірсинг вуха', true, 3) on conflict (id) do nothing;
insert into settings (id, data) values ('info', '{"address": "вул. Городоцька, 47", "city": "Львів", "address_note": "Вхід з вулиці, чорні двері з неоном", "map_query": "Horodotska St 47, Lviv, Ukraine", "phone": "+380 32 247 47 47", "phone_note": "Дзвінки щодня з 11:00", "hours": "Вт–Нд: 11:00–21:00", "hours_note": "Понеділок вихідний", "opening_hours": "Tu-Su 11:00-21:00", "instagram": "https://instagram.com/tattoohouse.lviv", "telegram": "https://t.me/tattoohouse_lviv", "stats": {"rating": 4.9, "reviews": 1200, "clients": 5000, "years": 10}}'::jsonb) on conflict (id) do nothing;
